using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Runtime.Serialization.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;

namespace MaohaiziPet {
public static class MotionClipTests {
    static LivingReport report;
    static void Assert(bool ok,string error){if(!ok)throw new Exception(error);}
    static byte[] Pixels(BitmapSource image){int size=image.PixelWidth;byte[] result=new byte[size*image.PixelHeight*4];new FormatConvertedBitmap(image,PixelFormats.Pbgra32,null,0).CopyPixels(result,size*4,0);return result;}
    static BitmapSource Neutral(PetSkin skin,MotionClip clip){var visual=new DrawingVisual();using(var d=visual.RenderOpen())d.DrawImage(skin.Frames[0],new Rect(-clip.Spec.originX,-clip.Spec.originY,256,256));var image=new RenderTargetBitmap(clip.Size,clip.Size,96,96,PixelFormats.Pbgra32);image.Render(visual);return image;}
    static BitmapSource PoseAnchor(PetSkin skin,MotionClip clip){if(!MotionLibrary.IsPoseActivity(clip.Spec.id))return Neutral(skin,clip);var parent=skin.Motions.Clips[clip.Spec.parentPose];if(parent.Size==clip.Size)return parent.Frames[parent.Spec.holdAt];var visual=new DrawingVisual();using(var d=visual.RenderOpen())d.DrawImage(parent.Frames[parent.Spec.holdAt],new Rect((clip.Size-parent.Size)/2,(clip.Size-parent.Size)/2,parent.Size,parent.Size));var image=new RenderTargetBitmap(clip.Size,clip.Size,96,96,PixelFormats.Pbgra32);image.Render(visual);return image;}
    static void Check(string name,Action run){var r=new TestResult{name=name};try{run();r.passed=true;report.passed++;}catch(Exception e){r.error=e.ToString();report.failed++;}report.tests.Add(r);}
    static MotionSpec Spec(){return new MotionSpec{id="groom",sheet="motion-groom.png",columns=8,rows=1,frames=8,fps=12,reviewed=true};}
    static void Manifest(string path,MotionSpec spec){using(var f=File.Create(Path.Combine(path,"motions.json")))new DataContractJsonSerializer(typeof(MotionManifest)).WriteObject(f,new MotionManifest{clips=new[]{spec}});}
    static void ManifestClips(string path,params MotionSpec[] clips){using(var f=File.Create(Path.Combine(path,"motions.json")))new DataContractJsonSerializer(typeof(MotionManifest)).WriteObject(f,new MotionManifest{clips=clips});}
    static void Fixture(string path){
        // Artificial test squares, never used as cat animation or sales imagery.
        Directory.CreateDirectory(path);var v=new DrawingVisual();using(var d=v.RenderOpen())for(int i=0;i<8;i++)d.DrawRoundedRectangle(new SolidColorBrush(Color.FromRgb((byte)(40+i*25),115,140)),null,new Rect(i*256+60+i*12,100,32,32),4,4);
        var b=new RenderTargetBitmap(2048,256,96,96,PixelFormats.Pbgra32);b.Render(v);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(Path.Combine(path,"motion-groom.png")))png.Save(f);Manifest(path,Spec());
        foreach(bool green in new[]{false,true}){
            string folder=Path.Combine(path,green?"green-frames":"transparent-frames");Directory.CreateDirectory(folder);
            for(int i=0;i<8;i++){var frame=new DrawingVisual();using(var d=frame.RenderOpen()){if(green)d.DrawRectangle(Brushes.Lime,null,new Rect(0,0,256,256));d.DrawImage(new CroppedBitmap(b,new Int32Rect(i*256,0,256,256)),new Rect(0,0,256,256));}var rendered=new RenderTargetBitmap(256,256,96,96,PixelFormats.Pbgra32);rendered.Render(frame);var output=new PngBitmapEncoder();output.Frames.Add(BitmapFrame.Create(rendered));using(var f=File.Create(Path.Combine(folder,"frame-"+i.ToString("D5")+".png")))output.Save(f);}
        }
    }
    static void Reject(string path,MotionSpec spec){Manifest(path,spec);bool rejected=false;try{MotionLibrary.Load(path);}catch(InvalidDataException){rejected=true;}Assert(rejected,"非法动作参数被接收");}
    public static int Run(string manifest,string output){
        Directory.CreateDirectory(output);report=new LivingReport();report.scope="Synthetic playback fixtures plus actual generated cat frames: neutral anchors, grounding, interruption recovery, package roundtrip and validation";
        string fixture=Path.Combine(output,"synthetic-fixture");Fixture(fixture);MotionLibrary library=MotionLibrary.Load(fixture);MotionClip clip=library.Clips["groom"];
        Check("空动作库不启用未完成动作",delegate{string empty=Path.Combine(output,"empty");Directory.CreateDirectory(empty);Assert(MotionLibrary.Load(empty).Clips.Count==0,"无素材时启用动作");});
        Check("待审核素材不会仅因存在文件而自动上线",delegate{var spec=Spec();spec.reviewed=false;Manifest(fixture,spec);Assert(MotionLibrary.Load(fixture).Clips.Count==0,"草稿被启用");Manifest(fixture,Spec());});
        Check("稀疏姿态插帧即使标记已审核也不能冒充连续起身动作",delegate{var spec=Spec();spec.id="stand";spec.sheet="motion-stand.png";spec.transitionSource="sparse-keyframe-flow";File.Copy(Path.Combine(fixture,"motion-groom.png"),Path.Combine(fixture,"motion-stand.png"),true);Manifest(fixture,spec);Assert(MotionLibrary.Load(fixture).Clips.Count==0,"未通过物理过渡验收的姿态被启用");spec.physicalTransitionReviewed=true;Manifest(fixture,spec);Assert(MotionLibrary.Load(fixture).Clips.Count==0,"稀疏插帧被当成骨骼动作");Manifest(fixture,Spec());});
        Check("连续序列来源与物理过渡验收必须同时具备",delegate{var spec=Spec();spec.id="stand";spec.sheet="motion-stand.png";spec.transitionSource="continuous-video";Manifest(fixture,spec);Assert(MotionLibrary.Load(fixture).Clips.Count==0,"只有来源标记就开放了姿态");spec.physicalTransitionReviewed=true;Manifest(fixture,spec);Assert(MotionLibrary.Load(fixture).Clips.ContainsKey("stand"),"有效验收标记不能开放素材");Manifest(fixture,Spec());});
        Check("逐帧播放顺序、末帧与自然退出",delegate{var p=new MotionPlayer();p.Start(clip,1);int last=-1;var seen=new HashSet<int>();for(int i=0;i<90;i++){if(p.Active){Assert(p.FrameIndex>=last,"播放顺序倒退");last=p.FrameIndex;seen.Add(last);}p.Tick(1.0/60);}Assert(seen.Count==8&&!p.Active,"帧被跳过或没有结束");});
        Check("打断时沿原动作帧收回，不瞬间跳回待机",delegate{var p=new MotionPlayer();p.Start(clip,1);p.Tick(.7);int start=p.FrameIndex;p.Cancel();Assert(p.Active&&p.Recovering&&p.FrameIndex==start,"打断时硬切");int last=p.FrameIndex;for(int i=0;i<120;i++){p.Tick(1.0/60);if(p.Active){Assert(p.FrameIndex<=last,"恢复顺序错误");last=p.FrameIndex;}}Assert(!p.Active,"恢复未结束");});
        Check("切换动作先恢复，再从新动作第一帧播放",delegate{var p=new MotionPlayer();p.Start(clip,1);p.Tick(.7);p.Start(clip,1);Assert(p.Recovering,"切换动作硬切");bool restarted=false;for(int i=0;i<120;i++){p.Tick(.01);if(p.Active&&!p.Recovering){Assert(p.FrameIndex==0,"新动作没有从第一帧开始");restarted=true;break;}}Assert(restarted,"新动作被丢失");});
        Check("透明点击区域随当前姿态变化",delegate{var p=new MotionPlayer();p.Start(clip,1);Assert(p.Hit(65,110)&&!p.Hit(145,110)&&!p.Hit(0,0),"第一帧命中区域错误");p.Tick(.95);Assert(!p.Hit(65,110)&&p.Hit(137,110),"仍使用待机轮廓命中");});
        Check("动作参数与文件路径边界",delegate{var spec=Spec();spec.sheet="../bad.png";Reject(fixture,spec);spec=Spec();spec.frames=999;Reject(fixture,spec);spec=Spec();spec.fps=double.NaN;Reject(fixture,spec);spec=Spec();spec.sheet="atlas.png";Reject(fixture,spec);Manifest(fixture,Spec());});
        Check("无损去重保留每一帧的顺序和停留时长，重复帧共用位图",delegate{var spec=Spec();spec.frameMap=new[]{7,6,6,5,3,2,1,0};Manifest(fixture,spec);var packed=MotionLibrary.Load(fixture).Clips["groom"];Assert(Pixels(packed.Frames[0]).SequenceEqual(Pixels(clip.Frames[7]))&&object.ReferenceEquals(packed.Frames[1],packed.Frames[2])&&packed.Frames.Length==8,"去重改变时序或重复解码");spec.frameMap=new[]{0,1};Reject(fixture,spec);spec.frameMap=new[]{0,1,2,3,4,5,6,8};Reject(fixture,spec);Manifest(fixture,Spec());});
        Check("倒放左向素材不能冒充右向行走",delegate{var left=Spec();left.id="walk-left";left.sheet="motion-walk-left.png";left.transitionSource="continuous-video";left.physicalTransitionReviewed=true;left.pathFollowsFrame=true;left.frameMap=Enumerable.Range(0,8).ToArray();left.travelX=new double[]{0,0,-1,-2,-3,-4,-5,-5};File.Copy(Path.Combine(fixture,"motion-groom.png"),Path.Combine(fixture,left.sheet),true);var right=Spec();right.id="walk-right";right.sheet=left.sheet;right.derivedFrom="walk-left";right.transitionSource="continuous-video";right.physicalTransitionReviewed=true;right.pathFollowsFrame=true;right.frameMap=left.frameMap.Reverse().ToArray();right.travelX=left.travelX.Reverse().Select(x=>x+5).ToArray();ManifestClips(fixture,left,right);bool failed=false;try{MotionLibrary.Load(fixture);}catch(InvalidDataException){failed=true;}Assert(failed,"倒放左向素材仍然可以作为右向步态加载");right.sheet="motion-walk-right.png";File.Copy(Path.Combine(fixture,left.sheet),Path.Combine(fixture,right.sheet),true);ManifestClips(fixture,left,right);failed=false;try{MotionLibrary.Load(fixture);}catch(InvalidDataException){failed=true;}Assert(failed,"仅改图集名即可绕过倒放检查");Manifest(fixture,Spec());});
        Check("裁切补偿与图像取同一帧，不提前插值造成脚底抖动",delegate{var spec=Spec();spec.id="walk-right";spec.pathFollowsFrame=true;spec.travelX=new double[]{0,0,1,2,3,4,5,5};spec.travelY=new double[]{0,0,.5,1,1,1,1,1};var p=new MotionPlayer();var c=new MotionClip(spec,clip.Frames);p.Start(c,c.Seconds);p.Tick(2.5/(7/c.Seconds));Assert(p.FrameIndex==2&&p.Displacement==1&&p.DisplacementY==.5,"位移与当前图像帧失去同步");});
        Check("动作包导入导出保留素材与审核状态",delegate{var skin=PetSkin.Load(manifest);skin.Motions=library;string zip=Path.Combine(output,"fixture-motion-pack.zip");skin.Export(zip);var restored=PetSkin.Load(PetSkin.Import(zip,Path.Combine(output,"imported")));Assert(restored.Motions.Clips.ContainsKey("groom")&&restored.Motions.Clips["groom"].Frames.Length==8,"动作素材丢失");});
        Check("正在做同一种动作时再次点击不会重新开始",delegate{var h=new CatHabits(2){GroomReady=true};h.Start(CatHabit.Groom,PetMode.Companion,false);int first=h.Revision;h.Tick(1,PetMode.Companion,false,false);Assert(!h.Start(CatHabit.Groom,PetMode.Companion,false)&&h.Revision==first&&h.Age==1,"重复点击重置了动作");});
        Check("单次动作停留时不重播帧，收尾只走一遍",delegate{var spec=Spec();spec.holdAt=3;spec.holdSeconds=2;var held=new MotionClip(spec,clip.Frames);var p=new MotionPlayer();p.Start(held,held.Seconds);p.Tick(3.0/12);Assert(p.HoldingPose&&p.FrameIndex==3,"没有停留在指定姿态");p.Tick(1.5);Assert(p.HoldingPose&&p.FrameIndex==3,"自然停留重新播放了动作");int last=p.FrameIndex;for(int i=0;i<120;i++){p.Tick(1.0/60);if(p.Active){Assert(p.FrameIndex>=last,"动作片段回放或倒退");last=p.FrameIndex;}}Assert(!p.Active,"动作没有收尾");});
        Check("停留姿态被打断时先平滑收束，再沿收尾前进",delegate{var spec=Spec();spec.holdAt=3;spec.holdSeconds=2;var held=new MotionClip(spec,clip.Frames);var p=new MotionPlayer();p.Start(held,held.Seconds);p.Tick(.5);p.Cancel();p.Tick(.1);Assert(p.Recovering&&p.HoldingPose&&p.FrameIndex==3,"打断时突然跳离当前姿态");p.Tick(.2);Assert(p.Active&&!p.HoldingPose&&p.FramePosition>3,"打断后倒放了起身过程");p.Tick(1);Assert(!p.Active,"收尾不能完成");});
        Check("重复循环、非法停留和扩展画布参数被拒绝",delegate{var spec=Spec();spec.loopCycles=3;Reject(fixture,spec);spec=Spec();spec.holdAt=7;spec.holdSeconds=2;Reject(fixture,spec);spec=Spec();spec.holdSeconds=double.NaN;Reject(fixture,spec);spec=Spec();spec.size=320;spec.originY=10;Reject(fixture,spec);Manifest(fixture,Spec());});
        Check("走动必须有同向有限轨迹和完整面部跟踪，不能滑动静态照片",delegate{
            var spec=Spec();spec.id="walk-left";spec.sheet="motion-walk-left.png";File.Copy(Path.Combine(fixture,"motion-groom.png"),Path.Combine(fixture,spec.sheet),true);Reject(fixture,spec);
            spec.travelX=new double[]{0,0,-1,-2,-3,-4,-5,-5};spec.noseX=Enumerable.Repeat(140.0,8).ToArray();Reject(fixture,spec);spec.noseY=Enumerable.Repeat(113.0,8).ToArray();spec.noseY[3]=double.NaN;Reject(fixture,spec);spec.noseY[3]=113;spec.travelX[4]=2;Reject(fixture,spec);spec.travelX[4]=-3;spec.transitionSource="continuous-video";spec.physicalTransitionReviewed=true;Manifest(fixture,spec);Assert(MotionLibrary.Load(fixture).Clips.ContainsKey("walk-left"),"合法步态不能载入");Manifest(fixture,Spec());
        });
        Check("走动的触摸跟随猫脸，打断时继续落脚收尾而不倒走",delegate{
            var spec=Spec();spec.id="walk-right";spec.travelX=new double[]{0,0,1,2,3,4,5,5};spec.noseX=new double[]{140,142,145,150,155,154,145,140};spec.noseY=Enumerable.Repeat(113.0,8).ToArray();var walk=new MotionClip(spec,clip.Frames);var p=new MotionPlayer();p.Start(walk,walk.Seconds);p.Tick(.3);int at=p.FrameIndex;Assert(Math.Abs(p.TouchNose.X-spec.noseX[at])<.001,"猫脸触摸位置仍固定");double previous=p.Displacement;p.Cancel();int frame=p.FrameIndex;for(int i=0;i<90&&p.Active;i++){p.Tick(.01);if(p.Active){Assert(p.FrameIndex>=frame&&p.Displacement>=previous,"走动打断后倒放或后退");frame=p.FrameIndex;previous=p.Displacement;}}Assert(!p.Active,"步态打断无法完成");
        });
        Check("短姿态的触摸坐标随实际停留位置移动并回到待机",delegate{
            var spec=Spec();spec.id="stand";spec.anchorFrames=1;spec.holdAt=3;spec.holdSeconds=2;spec.eyeLeftX=80;spec.eyeRightX=112;spec.eyeLeftY=spec.eyeRightY=50;
            var held=new MotionClip(spec,clip.Frames);var p=new MotionPlayer();p.Start(held,held.Seconds);
            Assert((p.TouchNose-new Point(140,113)).Length<.001,"起点触摸位置不在待机猫脸上");
            p.Tick(.25);Assert(p.HoldingPose&&(p.TouchNose-new Point(96,69)).Length<.001,"短片仍套用旧素材的固定66帧时序");
            p.Tick(2.25);Assert(p.Active&&!p.HoldingPose&&(p.TouchNose-new Point(140,113)).Length<.001,"收尾触摸坐标没有回到待机");
            spec.size=320;spec.originX=spec.originY=-32;p.Start(held,held.Seconds);while(p.Recovering)p.Tick(.05);p.Tick(.25);
            Assert(p.HoldingPose&&(p.TouchNose-new Point(64,37)).Length<.001,"扩展画布的触摸坐标没有应用原点");
        });
        var real=PetSkin.Load(manifest);
        if(real.Motions!=null&&real.Motions.Clips.Count>0){
            Check("舔毛使用已复核的原生连续素材，避免重新打包旧的重影插帧",delegate{var groom=real.Motions.Clips["groom"].Spec;Assert(groom.transitionSource=="continuous-video"&&groom.physicalTransitionReviewed,"舔毛仍来自未经复核的旧插帧素材；来源标记不能代替实际逐帧审图");});
            Check("正式左右行走使用正放步态，不以时间倒放替代右向行走",delegate{var left=real.Motions.Clips["walk-left"].Spec;var right=real.Motions.Clips["walk-right"].Spec;Assert(string.IsNullOrEmpty(left.derivedFrom)&&string.IsNullOrEmpty(right.derivedFrom)&&left.sheet!=right.sheet,"正式步态仍然引用倒放素材");Assert(left.travelX.Last()<0&&right.travelX.Last()>0&&left.pathFollowsFrame&&right.pathFollowsFrame,"正式步态缺少正确方向与逐帧位移");});
            Check("已启用生成动作均为完整透明序列且实际帧内容变化",delegate{
                // Native posture entries can take 1.5 seconds, shorter than
                // the legacy five-second grooming/yawn clips. Preserve the
                // native 24 fps and reject sparse sixteen-pose substitutes.
                foreach(var pair in real.Motions.Clips){var c=pair.Value;bool activity=MotionLibrary.IsPoseActivity(c.Spec.id),walking=MotionLibrary.IsWalk(c.Spec.id),posture=c.Spec.id=="sit"||c.Spec.id=="stand"||c.Spec.id=="sleep"||c.Spec.id=="belly";Assert(c.Frames.Length>=(activity?48:posture?84:120)&&c.Frames.Length<=(walking?640:c.Spec.id=="stand"?320:240)&&c.Spec.fps==24,"实际序列帧数或帧率错误");var unique=new HashSet<string>();
                    using(var hash=System.Security.Cryptography.SHA256.Create())foreach(var f in c.Frames){byte[] data=Pixels(f);Assert(data[3]<=5,"背景角落不透明");unique.Add(Convert.ToBase64String(hash.ComputeHash(data)));}
                    Assert(unique.Count>=(activity?20:posture?30:60),"动作退化为反复播放相同静帧");
                }
            });
            Check("完整动作回到原待机，小活动始终衔接对应的持续姿态",delegate{foreach(var c in real.Motions.Clips.Values){bool activity=MotionLibrary.IsPoseActivity(c.Spec.id);byte[] neutral=Pixels(PoseAnchor(real,c));int anchors=activity?8:12;Assert(c.Spec.anchorFrames==anchors,"没有预留起止时间");for(int i=0;i<anchors;i++){foreach(int at in new[]{i,c.Frames.Length-1-i}){byte[] actual=Pixels(c.Frames[at]);double error=actual.Zip(neutral,(a,b)=>Math.Abs(a-b)).Average();Assert(error<.2,"起止姿态不连续："+c.Spec.id+" "+at+" delta="+error);}}}});
            Check("完整动作的支撑爪保持接地，伸出的玩耍爪不冒充支撑脚",delegate{foreach(var c in real.Motions.Clips.Values)foreach(var frame in c.Frames){if(c.Spec.id=="sit-jump")continue; // Airborne/landing bounds are checked in JumpPlayTests.
byte[] pixels=Pixels(frame);int floor=-1;bool play=c.Spec.pawX!=null;int minX=play?(c.Spec.id.EndsWith("right")?180:222):0,maxX=play?(c.Spec.id.EndsWith("right")?220:264):c.Size;for(int y=c.Size-1;y>=0&&floor<0;y--){int occupied=0;for(int x=minX;x<maxX;x++)if(pixels[(y*c.Size+x)*4+3]>=128)occupied++;if(occupied>=6)floor=y;}Assert(Math.Abs(floor-(235-c.Spec.originY))<=(play?2:0),"支撑脚接地位置漂移："+c.Spec.id+" "+floor);}});
            Check("动作进入与结束没有明显处理色差",delegate{foreach(var c in real.Motions.Clips.Values)foreach(int at in new[]{c.Spec.anchorFrames,c.Frames.Length-c.Spec.anchorFrames}){byte[] a=Pixels(c.Frames[at-1]),b=Pixels(c.Frames[at]);Assert(a.Zip(b,(x,y)=>Math.Abs(x-y)).Average()<.6,"起止衔接出现颜色或轮廓跳变");}});
            Check("习惯调度使用实际素材时长而非把16帧拖慢播放",delegate{var h=new CatHabits(2){GroomReady=true};double seconds=real.Motions.Clips["groom"].Seconds;h.SetMotionDuration(CatHabit.Groom,seconds);h.Start(CatHabit.Groom,PetMode.Companion,false);Assert(h.Duration==seconds,"动作时长没有跟随素材");h.Tick(seconds+.1,PetMode.Companion,false,false);Assert(!h.Active,"动作收尾后还在等待");});
            Check("完整哈欠素材不会明显变胖变瘦",delegate{double width=MotionQuality.TorsoWidth(real.Frames[0]),area=MotionQuality.SeatedArea(real.Frames[0]);foreach(var frame in real.Motions.Clips["yawn"].Frames){Assert(Math.Abs(MotionQuality.TorsoWidth(frame)/width-1)<=.06,"哈欠躯干宽度漂移超过6%");Assert(Math.Abs(MotionQuality.SeatedArea(frame)/area-1)<=.075,"哈欠下半身体量变化超过7.5%");}});
            Check("哈欠包含实际张嘴，不能把细微待机变化当作完整哈欠",delegate{var yawn=real.Motions.Clips["yawn"];int closed=MotionQuality.MouthAperture(yawn.Frames[0]);Assert(yawn.Frames.Max(f=>MotionQuality.MouthAperture(f))>=closed+35,"没有可见的嘴部张开");Assert(yawn.Spec.transitionSource=="continuous-video"&&yawn.Spec.physicalTransitionReviewed,"哈欠仍使用未经复核的插帧");});
            foreach(var pair in real.Motions.Clips.Where(v=>v.Value.HasHold)){var posture=pair.Value;Check(pair.Key+" 自然停留不循环完整动作，仍有轻微生命活动",delegate{
                var p=new MotionPlayer();p.Start(posture,posture.Seconds);p.Tick(posture.Spec.holdAt/posture.Spec.fps);Assert(p.HoldingPose,"没有进入停留");byte[] original=Pixels(posture.Frames[posture.Spec.holdAt]);Assert(Pixels(p.Image).SequenceEqual(original),"停留起点换了纹理");var images=new HashSet<string>();using(var hash=System.Security.Cryptography.SHA256.Create())for(int i=0;i<90;i++){p.Tick(1.0/60);Assert(p.HoldingPose&&p.FrameIndex==posture.Spec.holdAt,"停留期间回放了动作帧");images.Add(Convert.ToBase64String(hash.ComputeHash(Pixels(p.Image))));}Assert(images.Count>20,"停留变成了静止图片");int last=p.FrameIndex;while(p.Active){p.Tick(.05);if(p.Active){Assert(p.FrameIndex>=last,"收尾重新回放完整动作");last=p.FrameIndex;}}
            });}
            if(real.Motions.Clips.Values.Any(c=>c.HasHold))Check("完整素材包导出导入保留连续过渡与单次停留",delegate{string zip=Path.Combine(output,"complete-postures.zip");real.Export(zip);var roundtrip=PetSkin.Load(PetSkin.Import(zip,Path.Combine(output,"complete-roundtrip")));Assert(roundtrip.Motions.Clips.Count==real.Motions.Clips.Count,"新姿态丢失");foreach(var pair in real.Motions.Clips){var restored=roundtrip.Motions.Clips[pair.Key];Assert(restored.HasHold==pair.Value.HasHold&&restored.Size==pair.Value.Size&&restored.Spec.holdAt==pair.Value.Spec.holdAt&&restored.Spec.holdSeconds==pair.Value.Spec.holdSeconds&&restored.Spec.transitionSource==pair.Value.Spec.transitionSource&&restored.Spec.physicalTransitionReviewed==pair.Value.Spec.physicalTransitionReviewed&&restored.Spec.loopCycles<=1&&restored.Spec.parentPose==pair.Value.Spec.parentPose&&restored.Spec.standEntryAt==pair.Value.Spec.standEntryAt&&restored.Spec.standExitAt==pair.Value.Spec.standExitAt&&restored.Spec.sitEntryAt==pair.Value.Spec.sitEntryAt&&restored.Spec.sitExitAt==pair.Value.Spec.sitExitAt&&restored.Spec.gaitEntryAt==pair.Value.Spec.gaitEntryAt&&restored.Spec.gaitExitAt==pair.Value.Spec.gaitExitAt,"连续来源、驻留衔接或停留参数丢失");}});
        }
        using(var f=File.Create(Path.Combine(output,"motion-test-report.json")))new DataContractJsonSerializer(typeof(LivingReport)).WriteObject(f,report);return report.failed==0?0:1;
    }
}
}
